import sys
import requests
import hashlib
import os
from urllib.parse import urljoin

def fetch_manifest(url):
    response = requests.get(url)
    response.raise_for_status()
    return response.text

def parse_manifest(xml_text):
    from xml.etree import ElementTree as ET
    root = ET.fromstring(xml_text)
    return {
        'file_url': root.find('file_url').text,
        'file_name': root.find('file_name').text,
        'hash_algorithm': root.find('hash_algorithm').text,
        'expected_hash': root.find('expected_hash').text
    }

def compute_hash(data, algorithm):
    hash_func = getattr(hashlib, algorithm)
    return hash_func(data).hexdigest().lower()

def verify_file(manifest):
    file_url = manifest['file_url']
    file_name = manifest['file_name']
    algorithm = manifest['hash_algorithm']
    expected_hash = manifest['expected_hash']

    try:
        response = requests.get(file_url, stream=True)
        response.raise_for_status()
        data = b''.join(bytearray(chunk) for chunk in response.iter_content(chunk_size=8192))
    except requests.RequestException:
        print("FAIL")
        return

    computed_hash = compute_hash(data, algorithm)

    if computed_hash == expected_hash:
        try:
            with open(file_name, 'wb') as f:
                f.write(data)
            print("OK")
        except IOError:
            print("FAIL")
    else:
        print("FAIL")

def main():
    if len(sys.argv) != 2:
        print("Usage: python fetch_verified.py <manifest_url>")
        sys.exit(1)

    manifest_url = sys.argv[1]
    xml_text = fetch_manifest(manifest_url)
    manifest = parse_manifest(xml_text)
    verify_file(manifest)

if __name__ == "__main__":
    main()
